set session_replication_role = replica;
create temp table _m1 as select id as old_id, gen_random_uuid() as new_id from parks where name not like '% cp_';
insert into parks (id, slug, name, commune_id,formatted_address,lat,lng,age_min,age_max,surface,wc,shade,fenced,pmr,benches,water,parking,play_equipment,photos,description,status,created_by,views,rating,review_count,has_open_report,created_at,updated_at,latitude,longitude,boundary,country_code,timezone,address_line,postal_code,city,admin_area_1,admin_area_2,min_age,max_age,ages_derived,moderation_status,operational_status,status_reason,status_from,status_until,verification_status,last_verified_at) select m.new_id, coalesce(p.slug,p.id::text)||'-cp1', p.name||' cp1', p.commune_id,p.formatted_address,p.lat,p.lng,p.age_min,p.age_max,p.surface,p.wc,p.shade,p.fenced,p.pmr,p.benches,p.water,p.parking,p.play_equipment,p.photos,p.description,p.status,p.created_by,p.views,p.rating,p.review_count,p.has_open_report,p.created_at,p.updated_at,p.latitude,p.longitude,p.boundary,p.country_code,p.timezone,p.address_line,p.postal_code,p.city,p.admin_area_1,p.admin_area_2,p.min_age,p.max_age,p.ages_derived,p.moderation_status,p.operational_status,p.status_reason,p.status_from,p.status_until,p.verification_status,p.last_verified_at from parks p join _m1 m on m.old_id=p.id;
insert into park_sources (id, park_id, source_type, source_name, source_url, license, last_synced_at, created_at)
  select gen_random_uuid(), m.new_id, s.source_type, s.source_name, s.source_url, s.license, s.last_synced_at, s.created_at from park_sources s join _m1 m on m.old_id=s.park_id;
insert into park_features (park_id, feature_id, status, value, quantity, verified_at)
  select m.new_id, f.feature_id, f.status, f.value, f.quantity, f.verified_at from park_features f join _m1 m on m.old_id=f.park_id;
